# Search inverted repeats: for each position i, find longest reverse-complement match starting at i and ending at j
def find_ir(minlen=10):
    hits = []
    for i in range(n):
        for j in range(i+minlen, n+1):
            L = j - i
            if L > 200: break
            sub = seq[i:j]
            # reverse complement match somewhere after
            r = rc(sub)
            k = seq.find(r, j+ minlen)
            if k != -1:
                hits.append((i, j, k, k+L, L))
    return hits
